  /* ================= Helpers ================= */
  function $(root, sel) { return root.querySelector(sel); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  function rand(a, b) { return a + Math.random() * (b - a); }

  // Sharp canvas on high-DPI screens. Game code draws in W x H units.
  function setupCanvas(canvas, W, H) {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    canvas.style.width = '100%'; canvas.style.maxWidth = W + 'px';
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return ctx;
  }
  function canvasPoint(canvas, e, W, H) {
    const r = canvas.getBoundingClientRect();
    return { x: (e.clientX - r.left) * (W / r.width), y: (e.clientY - r.top) * (H / r.height) };
  }
  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
  }
  // Torn-style "T" badge used as food and targets.
  function drawBadge(ctx, cx, cy, r, ring) {
    ctx.save();
    ctx.beginPath(); ctx.arc(cx, cy + 1.5, r, 0, Math.PI * 2); ctx.fillStyle = 'rgba(0,0,0,.28)'; ctx.fill();
    const g = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, r * 0.1, cx, cy, r);
    g.addColorStop(0, '#4a97ea'); g.addColorStop(1, '#173257');
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    ctx.lineWidth = Math.max(2, r * 0.12); ctx.strokeStyle = ring || '#9ec3ff'; ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = '900 ' + Math.floor(r * 1.05) + 'px system-ui,Arial,sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('T', cx, cy + r * 0.06);
    ctx.beginPath(); ctx.ellipse(cx - r * 0.25, cy - r * 0.45, r * 0.45, r * 0.18, -0.4, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,.18)'; ctx.fill();
    ctx.restore();
  }
  // A card in the middle of a canvas with a title and lines of text. The last line is the hint.
  function drawCanvasMsg(ctx, W, H, title, lines) {
    ctx.save();
    ctx.fillStyle = 'rgba(4,8,14,.5)'; ctx.fillRect(0, 0, W, H);
    const cw = Math.min(W - 40, 420), ch = 78 + lines.length * 26, x = (W - cw) / 2, y = (H - ch) / 2;
    ctx.shadowColor = 'rgba(0,0,0,.55)'; ctx.shadowBlur = 26; ctx.shadowOffsetY = 8;
    roundRect(ctx, x, y, cw, ch, 16); ctx.fillStyle = 'rgba(13,22,35,.97)'; ctx.fill();
    ctx.shadowColor = 'transparent'; ctx.lineWidth = 2; ctx.strokeStyle = '#2f7bd1'; ctx.stroke();
    roundRect(ctx, x + cw / 2 - 28, y - 3, 56, 6, 3); ctx.fillStyle = '#5aa3ef'; ctx.fill();
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff'; ctx.font = '800 28px system-ui,Arial,sans-serif'; ctx.fillText(title, W / 2, y + 40);
    lines.forEach(function (l, i) {
      const hint = i === lines.length - 1;
      ctx.font = (hint ? '700 ' : '500 ') + '15px system-ui,Arial,sans-serif';
      ctx.fillStyle = hint ? '#7fb2f0' : '#c3d2e4';
      ctx.fillText(l, W / 2, y + 78 + i * 26);
    });
    ctx.restore();
  }
  // Draws once into an off-screen canvas (W x H units) for fast reuse.
  function offscreen(W, H, drawFn) {
    const dpr = Math.min(2, window.devicePixelRatio || 1), c = document.createElement('canvas');
    c.width = Math.round(W * dpr); c.height = Math.round(H * dpr);
    const g = c.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); drawFn(g); return c;
  }
  // Confetti burst over an element (used for wins and new bests).
  function confetti(host) {
    const r = host.getBoundingClientRect(), Wc = Math.max(1, r.width), Hc = Math.max(1, r.height);
    const c = offscreen(Wc, Hc, function () {}), g = c.getContext('2d');
    c.className = 'ta-confetti'; c.style.width = Wc + 'px'; c.style.height = Hc + 'px';
    host.appendChild(c);
    const cols = ['#2f7bd1', '#5aa3ef', '#ffd65a', '#3fbf6a', '#e05a5a', '#ffffff'], ps = [];
    for (let i = 0; i < 140; i++) ps.push({ x: Wc / 2 + rand(-60, 60), y: Hc * 0.4, vx: rand(-340, 340), vy: rand(-560, -180), w: rand(5, 9), h: rand(8, 14), a: rand(0, 6.28), va: rand(-10, 10), c: cols[i % cols.length] });
    let start = 0, prev = 0;
    (function f(ts) {
      if (!start) start = prev = ts;
      const dt = Math.min(0.05, (ts - prev) / 1000), age = (ts - start) / 1000; prev = ts;
      g.clearRect(0, 0, Wc, Hc);
      g.globalAlpha = Math.max(0, 1 - Math.max(0, age - 1.4) / 0.6);
      ps.forEach(function (p) {
        p.vy += 900 * dt; p.vx *= 0.99; p.x += p.vx * dt; p.y += p.vy * dt; p.a += p.va * dt;
        g.save(); g.translate(p.x, p.y); g.rotate(p.a); g.fillStyle = p.c;
        g.fillRect(-p.w / 2, -p.h / 2, p.w, Math.max(1, Math.abs(Math.cos(p.a * 2)) * p.h)); g.restore();
      });
      if (age < 2) requestAnimationFrame(f); else c.remove();
    })(performance.now());
  }
  // A thin time bar under a game's stats. Returns a setter: (fraction left, low?).
  function timebar(panel) {
    $(panel, '.ta-stats').insertAdjacentHTML('afterend', '<div class="ta-timebar"><i></i></div>');
    const bar = $(panel, '.ta-timebar'), fill = $(bar, 'i');
    return function (frac, low) { fill.style.transform = 'scaleX(' + clamp(frac, 0, 1) + ')'; bar.classList.toggle('ta-low', !!low); };
  }
  function isTyping(t) {
    if (!t) return false;
    if (t.isContentEditable) return true;
    if (!t.closest) return false;
    const el = t.closest('input,textarea,select');
    if (!el) return false;
    if (el.tagName === 'INPUT') return ['checkbox', 'radio', 'button', 'submit', 'reset', 'range', 'color'].indexOf((el.type || '').toLowerCase()) === -1;
    return true;
  }
  function keyName(e) { return e.key && e.key.length === 1 ? e.key.toLowerCase() : e.key; }

  /* ================= Shell: the Mobile Phone ================= */
  const GAMES = [
    { id: 'pocket', name: 'Tornies',        icon: '🐾', bg: ['#4fd8b8', '#0f7a6a'] , desc: 'A creature-collecting adventure across Torn City. Catch 178 Tornies, win 8 Arena medals and take on the Torn Council.' },
    { id: 'invasion', name: 'Invasion', title: 'Torn Invasion', icon: '👽', bg: ['#6be38a', '#14532a'] , desc: 'A 3D alien shooter. Fight through alien-infested Torn City with pistol, shotgun and plasma rifle. Needs the free Torn Invasion add-on.' },
    { id: 'bogies', name: 'Angry Bogies', icon: '😠', bg: ['#ff9a5a', '#c8382a'] , desc: 'Bogie versus the Racket. Fling Bogies from a slingshot, smash the hideouts and knock out every thug. Fifteen levels, three stars each.' },
    { id: 'defence', name: 'Faction Defence', icon: '🛡️', bg: ['#7fb0ff', '#2a4f9a'], desc: 'Hold your Faction HQ against Racket raids. Build and upgrade defenders beside the road, survive 30 waves on 6 maps and spend your War Chest in the Armoury.' },
    { id: 'bombs',  name: 'Dirty Bombs',    icon: '☢️', bg: ['#ffe066', '#c99a10'] , desc: 'Clear the city block by block without setting off a dirty bomb. Numbers show how many bombs are nearby.' },
    { id: 'flappy', name: 'Flappy Torn',    icon: '🐦', bg: ['#6cc8ff', '#1f72c8'] , desc: 'Fly through the gaps in the pipes over Torn City. Every pipe you pass is a point.' },
    { id: 'eggdash', name: 'Egg Dash', title: "Anton's Egg Dash", icon: '🐰', bg: ['#8a5ae8', '#2a1458'], desc: 'Run the rooftops of Torn City as Anton in his bunny onesie. Grab the Easter eggs, jump the gaps and stay ahead of the police. One endless run that keeps getting faster.' },
    { id: 'territories', name: 'Territories', title: 'Torn Territories', icon: '🏘️', bg: ['#4a8ad8', '#1a3a6a'], desc: 'A district-building board game. Build roads, safehouses and HQs across Torn City, trade with rival factions and dodge the police raids. Classic (first to 14 Respect) or the Flight Paths expansion: fly to islands named after Torn\'s travel destinations (first to 12 or 16). Play against the computer, pass-and-play or online.' },
    { id: 'chess', name: 'Chess', title: 'Chess', icon: '♞', bg: ['#e8c88a', '#7a5230'], desc: 'Classic chess against the computer (Easy, Normal, Hard), or online against other Torn players with Quick match, public games and invites. 45 seconds a move online.' },
  ];
  // Home-screen icons for the games: small WebP pictures stored as text in the script (nothing is downloaded).
