      for (let i = -12; i <= 12; i++) { g.beginPath(); g.moveTo(W / 2 + i * 8, 600); g.lineTo(W / 2 + i * 70, H); g.stroke(); }
      for (let y = 610; y < H; y += (y - 590) * 0.35) { g.beginPath(); g.moveTo(0, y); g.lineTo(W, y); g.stroke(); }
