  ITEM_ORDER.splice(1, 0, 'capsule2', 'capsule3', 'federal');
  ITEM_ORDER.splice(ITEM_ORDER.indexOf('super_potion') + 1, 0, 'hyper_potion', 'revive', 'full_heal');
  DISCS.forEach(function (m) { ITEM_ORDER.push('disc_' + m); });
  ITEM_ORDER.push('rod', 'cutters', 'cardkey', 'vaultkey');
  function canLearnDisc(mon, mvId) {
    const M = MOVES[mvId], types = SP[mon.sp].types;
    return SP[mon.sp].allDiscs || M.type === 'Street' || types.indexOf(M.type) >= 0 || SP[mon.sp].learn.some(function (l) { return l[1] === mvId; });
  }

