  /* ---------- Tornies 172-177 (2.7.0): deep-water fish for the new rods, and the Battle Tower's own line ---------- */
  TN(172, 'Lurelet', ['Water', 'Shadow'], [45, 55, 40, 60, 45, 55], 120, 64, 'mf', [34, 173],
    'A little angler that dangles a glowing lure in the dark under the Docks. Night fishers follow the light and find it staring back.',
    { body: 'fish', c1: '#2a3a5a', c2: '#6a8ab0', c3: '#ffe066', head: 1.3, s: 0.62, crest: 'plume', teeth: 1, eye: '#ffe066' });
  TN(173, 'Gloomangler', ['Water', 'Shadow'], [90, 110, 80, 105, 85, 70], 45, 182, 'mf', null,
    'It waits in the deepest water in Torn City with its lure lit up like a shop sign. Whatever swims in to look never swims out.',
    { body: 'fish', c1: '#1a2238', c2: '#3a4e74', c3: '#8af0ff', s: 1.08, crest: 'plume', teeth: 1, fang: 1, fierce: 1, eye: '#8af0ff' }, [[40, 'shade_ball'], [46, 'tidal_crash']]);
  TN(174, 'Clampip', ['Water', 'Stone'], [50, 60, 90, 40, 55, 30], 140, 62, 'slow', [36, 175],
    'A clam that snaps shut on anything shiny. Harbour workers find wedding rings, watches and once a whole car key inside them.',
    { body: 'blob', c1: '#9a84b8', c2: '#f2e8f6', c3: '#ffffff', s: 0.62, armor: 1, spots: 1, eye: '#3a2a5a' });
  TN(175, 'Pearlord', ['Water', 'Stone'], [85, 100, 135, 95, 100, 50], 45, 186, 'slow', null,
    'A clam knight in a shell of polished mother-of-pearl. It guards a single perfect pearl that it will never, ever give you.',
    { body: 'biped', c1: '#6a5a8e', c2: '#ece0f4', c3: '#fff6e0', head: 0.95, s: 1.06, armor: 1, rocky: 1, crest: 'crest', fists: 1, fierce: 1, eye: '#ffcf5a' }, [[42, 'boulder_crash'], [48, 'tidal_crash']]);
  TN(176, 'Cadetling', ['Brawl', 'Metal'], [55, 70, 60, 35, 45, 55], 45, 68, 'slow', [40, 177],
    'A tiny trainee in a dented bucket helmet. Only hatches from Eggs won at the Battle Tower, and it salutes everyone it meets.',
    { body: 'biped', c1: '#8a909c', c2: '#dde0e8', c3: '#d84a2a', head: 1.3, s: 0.62, fists: 1, armor: 1, crest: 'tuft', eye: '#2a2a3a' });
  TN(177, 'Gladiatron', ['Brawl', 'Metal'], [90, 130, 110, 60, 85, 85], 45, 200, 'slow', null,
    'A Cadetling that has won a hundred fights in a row. Its armour is covered in the dents of every trainer who tried to stop it.',
    { body: 'biped', c1: '#5e6472', c2: '#c8ccd8', c3: '#e8b830', head: 0.9, s: 1.1, fists: 1, armor: 1, crest: 'blade', fierce: 1, eye: '#ff3a3a' }, [[45, 'iron_ram'], [52, 'uppercut']]);

  /* ---------- The APEX Tornie and the event mythic ---------- */
  mv('overmind', 'Overmind', 'Mind', 'S', 120, 100, 5);
  mv('daydream', 'Daydream', 'Mind', 'S', 70, 100, 15, { conf: 20 });
  // 178: APEX tier, above Legendary. TornTech built it from Mirabit's data. Waits at the bottom of the Origin Depths for Champions.
  TN(178, 'Synthex', ['Mind'], [120, 120, 100, 165, 100, 140], 3, 340, 'slow', null,
    'APEX TORNIE. TornTech rebuilt it from a single strand of Mirabit\'s data and gave it every power they could find. It broke out on day one and sank to the deepest point under Torn City.',
    { body: 'biped', c1: '#3a4060', c2: '#9ae0ff', c3: '#ff6a3a', head: 0.82, s: 1.18, ears: 'none', crest: 'horns', mane: 'spiky', tail: 'spike', armor: 1, fists: 1, fierce: 1, eye: '#5af0ff' }, [[50, 'overmind'], [60, 'mind_crush'], [70, 'ancient_roar']]);
  // 179: the event mythic. Only given out with a special gift code from Eaglewing. Can learn every Disc.
  TN(179, 'Mirabit', ['Mind'], [100, 100, 100, 100, 100, 100], 45, 270, 'slow', null,
    'So rare that most trainers think it\'s a myth. It carries a tiny copy of every Tornie\'s moves inside it, which is why it can learn anything.',
    { body: 'blob', c1: '#6ad8e8', c2: '#f4fcff', c3: '#ffc83a', s: 0.6, ears: 'pointy', crest: 'plume', spots: 1, eye: '#2a4ad8' }, [[1, 'daydream'], [40, 'mind_crush'], [50, 'overmind']]);
  SP[178].apex = 1;
  SP[179].event = 1; SP[179].allDiscs = 1;
  // The Tornie Log goal leaves out event-only Tornies (like the one you can only get from a gift code).
  const DEX_GOAL = DEX_SIZE - 1;
  function dexCount() { return Object.keys(G.caught || {}).filter(function (n) { return SP[n] && !SP[n].event; }).length; }

