  const MV_STAT = { atk: 'Power', def: 'Guard', spa: 'Focus', spd: 'Resolve', spe: 'Speed', acc: 'aim', eva: 'dodging' };
  const MV_ST = { brn: 'scorch', par: 'stun', psn: 'poison', slp: 'put to sleep', frz: 'freeze' };
  // Rules text built from the move data: what it does beyond plain damage.
  function moveEffects(M) {
    const f = M.fx || {}, out = [], c = f.c || 100;
    if (f.prio) out.push('Always goes first.');
    if (M.cat !== 'X' && M.acc === 0) out.push('Never misses.');
    if (f.hits) out.push(Array.isArray(f.hits) ? 'Hits 2-5 times in a row.' : 'Hits ' + f.hits + ' times in a row.');
    if (f.crit) out.push('High chance of a critical hit.');
    if (f.st) {
      const verb = MV_ST[f.st] || 'affect';
      out.push(M.cat === 'X' ? (f.st === 'slp' ? 'Puts the foe to sleep.' : f.st === 'psn' ? 'Poisons the foe.' : f.st === 'par' ? 'Stuns the foe.' : f.st === 'brn' ? 'Scorches the foe.' : 'Freezes the foe.')
        : c + '% chance to ' + verb + (f.st === 'slp' ? '' : ' the foe') + '.');
    }
    if (f.conf) out.push(f.conf + '% chance to daze the foe.');
    if (f.flinch) out.push(f.flinch + '% chance to make the foe lose its turn.');
    if (f.stat) f.stat.forEach(function (s) {
      const who = f.self ? 'its own' : 'the foe\'s', n = Math.abs(s[1]), up = s[1] > 0;
      const t = (up ? 'Raises ' : 'Lowers ') + who + ' ' + MV_STAT[s[0]] + (n > 1 ? ' sharply' : '') + '.';
      out.push(M.cat === 'X' || c >= 100 ? t : c + '% chance: ' + t.charAt(0).toLowerCase() + t.slice(1));
    });
    if (f.selfStat) f.selfStat.forEach(function (s) { const n = Math.abs(s[1]), t = (s[1] > 0 ? 'raise' : 'lower') + 's its own ' + MV_STAT[s[0]] + (n > 1 ? ' sharply' : '') + '.'; out.push(c >= 100 ? t.charAt(0).toUpperCase() + t.slice(1) : c + '% chance to ' + t.replace(/s its/, ' its')); });
    if (f.drain) out.push('Restores HP equal to ' + Math.round(f.drain * 100) + '% of the damage dealt.');
    if (f.heal) out.push('Restores ' + Math.round(f.heal * 100) + '% of its max HP.');
    if (f.recoil) out.push('The user takes ' + Math.round(f.recoil * 100) + '% of the damage dealt as recoil.');
    if (f.thaw) out.push('Thaws the user out if it is frozen.');
    return out.join(' ');
  }
  function moveDesc(id) { const M = MOVES[id]; if (!M) return ''; const e = moveEffects(M); return (MOVE_FLAVOUR[id] || '') + (e ? ' ' + e : ''); }
  // One line of numbers: category, power and accuracy.
  function moveStats(id) {
    const M = MOVES[id]; if (!M) return '';
    const cat = M.cat === 'P' ? 'Physical' : M.cat === 'S' ? 'Special' : 'Status';
    return cat + (M.pow ? '  ·  Power ' + M.pow : '') + '  ·  Accuracy ' + (M.acc ? M.acc + '%' : '—');
  }
  // Draws a move's details in a box: optional name, type chip and numbers, then the wrapped description.
  function drawMoveInfo(id, x, y, w, h, o) {
    const M = MOVES[id]; if (!M) return;
    o = o || {};
    box(x, y, w, h);
    let yy = y + 5;
    if (o.name) { text(M.name, x + 8, yy, '#303846', { sz: 9 }); if (o.right) text(o.right, x + w - 8, yy + 1, '#5a6474', { sz: 7, al: 'right' }); yy += 12; }
    typeChip(M.type, x + 8, yy, 40);
    text(moveStats(id), x + 53, yy + 1, '#5a6474', { sz: 6.5 });
    yy += 11;
    wrapText(moveDesc(id), w - 16, 6.5).forEach(function (l, k) { if (k === 0 || yy + k * 7.6 + 6.5 <= y + h - 2) text(l, x + 8, yy + k * 7.6, '#303846', { sz: 6.5, sh: false }); });
  }

  /* ---------- World extras: night, hidden things, fences, fishing, legends, taxi ---------- */
  let forceNight = null;   // tests can force day or night
  // The Ranked Charm (a post-game reward) triples the odds of meeting a Ranked Tornie.
  function rankedOdds() { return RANKED_ODDS * (G.bag && G.bag.rankcharm ? 3 : 1); }
  // Tornies keeps its own game clock, run by Tornies play time (it pauses whenever Tornies isn't being played).
  // One full cycle is 30 minutes: Morning 4 min, Day 10 min, Night 16 min. Morning counts as day for day/night
  // encounters. A new game starts at dawn.
  const DAY_CYCLE = [['morning', 240], ['day', 600], ['night', 960]], DAY_LEN = 1800;
  function dayPhase() {
    let t = ((G && G.time) || 0) % DAY_LEN;
    for (let k = 0; k < DAY_CYCLE.length; k++) {
      if (t < DAY_CYCLE[k][1]) return { name: DAY_CYCLE[k][0], left: DAY_CYCLE[k][1] - t, next: DAY_CYCLE[(k + 1) % DAY_CYCLE.length][0] };
      t -= DAY_CYCLE[k][1];
    }
    return { name: 'morning', left: 240, next: 'day' };
  }
  function timeOfDay() {
    if (forceNight !== null) return forceNight ? 'night' : 'day';
    return dayPhase().name;
  }
  // Shown beside the start menu: "Morning · 3 min to Day".
  function drawDayClock() {
    const ph = dayPhase(), cap = function (s) { return s.charAt(0).toUpperCase() + s.slice(1); };
    const mins = Math.max(1, Math.ceil(ph.left / 60));
    const t = (ph.name === 'night' ? '\u263e ' : '\u2600 ') + cap(ph.name) + ' \u00b7 ' + mins + ' min to ' + cap(ph.next);
    const w = Math.ceil(tw(t, 8) + 14);
    box(4, 4, w, 18);
    text(t, 11, 9, '#303846', { sz: 8 });
  }
  function isNight() { return timeOfDay() === 'night'; }
  function drawLighting(m, camX, camY) {
    const pp = lerpPos(W.p), px0 = pp[0] - camX + 8, py0 = pp[1] - camY + 6;
    if (m.dark && !(G.lit && G.lit[m.id])) {
      const gr = ctx.createRadialGradient(px0, py0, 26, px0, py0, 110);
      gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, 'rgba(0,0,0,0.88)');
      ctx.fillStyle = gr; ctx.fillRect(0, 0, VW, VH);
    }
    if (!m.indoor && timeOfDay() === 'morning') fr(0, 0, VW, VH, 'rgba(255,170,100,0.13)');   // soft morning light
    if (!m.indoor && isNight()) {
      fr(0, 0, VW, VH, 'rgba(12,16,58,0.55)');
      if (iwOn && store.get('detailMaps', true) !== false) iwNightWindows(m, camX, camY);
      ctx.save(); ctx.globalCompositeOperation = 'lighter';
      const x0 = Math.floor(camX / 16), y0 = Math.floor(camY / 16);
      for (let ty = y0 - 1; ty <= y0 + 11; ty++) for (let tx = x0 - 1; tx <= x0 + 16; tx++) {
        const t = tileAt(m, tx, ty);
        if (t !== 'L' && t !== 'N') continue;
        const cx = tx * 16 - camX + 8, cy = ty * 16 - camY + 4;
        const gr = ctx.createRadialGradient(cx, cy, 2, cx, cy, 30);
        gr.addColorStop(0, t === 'N' ? 'rgba(255,90,210,0.35)' : 'rgba(255,214,140,0.38)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = gr; ctx.fillRect(cx - 30, cy - 30, 60, 60);
      }
      ctx.restore();
    }
    if (!m.indoor) drawWeather(weatherNow(m), camX, camY);
  }
  function aOrAn(w) { return /^[AEIOU]/i.test(w) ? 'an' : 'a'; }

  const EGG_TOTAL = 10;
  async function findHidden(h) {
    G.found = G.found || {}; G.found[h[4]] = 1;
    if (h[2] === 'egg') {
      G.eggs = (G.eggs || 0) + 1; jingle('get');
      await say('{P} found a TORN EGG, painted in red, white and blue!|Torn Eggs found: ' + G.eggs + ' / ' + EGG_TOTAL);
      if (G.eggs >= EGG_TOTAL) await say('All ten eggs are humming quietly in your bag... Maybe the egg collector in Maple Hollow knows why.');
    } else if (h[2] === 'money') {
      G.money += h[3]; jingle('item');
      await say('{P} found $' + h[3] + ' stuffed out of sight!');
    } else {
      addItem(h[2], h[3]); jingle('item');
      const nm = ITEMS[h[2]].name;
      await say('{P} found ' + (h[3] > 1 ? h[3] + ' x ' + nm : aOrAn(nm) + ' ' + nm) + ' tucked out of sight!');
    }
    saveGame();
  }
  async function fenceCheck(x, y) {
    if (!G.bag.cutters) { await say('A chain-link fence. With the right tool you could cut a way through.'); return; }
    if (!(await yesno('A chain-link fence. Snip through it with the Bolt Cutters?'))) return;
    G.cut = G.cut || {}; G.cut[W.map.id + ':' + x + ',' + y] = 1;
    seq([[0, 1200, 0.04, 'square', 0.04], [70, 900, 0.05, 'square', 0.04]]);
    await say('Snip! There\'s a gap in the fence now.');
    saveGame();
  }
  async function fishHere() {
    const rods = RODS.filter(function (r) { return G.bag[r[0]]; });
    if (!rods.length) { await say('The water looks deep. A fishing rod would come in handy here.'); return; }
    let rod = rods[0];
    if (rods.length > 1) {
      const i = await ask('Which rod will you use?', rods.map(function (r) { return r[1].toUpperCase(); }).concat(['CANCEL']));
      if (i < 0 || i >= rods.length) return;
      rod = rods[i];
    }
    const table = rodTable(W.map, rod[0]);
    if (!table || !table.length) { await say('Nothing seems to live in this water.'); return; }
    const d = await say('{P} casts the ' + rod[1] + '...', { hold: true });
    await wait(0.8 + Math.random() * 1.2);
    pop(d);
    if (Math.random() < rod[2]) {
      tone(900, 0.1, 'square', 0.04); await say('Something\'s biting!');
      gstat('fishBites');
      const r = await wildBattle(table);
      if (r === 'caught') { gstat('fishCaught'); gstat('fish_' + rod[0]); }
      checkMerits();
    } else await say('Not even a nibble.');
  }
  async function legendEncounter(n) {
    const d = n.def;
    cry(d.sp);
    await say(d.text || 'It\'s watching you closely...');
    if (SP[d.sp].apex) await say('This is an APEX Tornie. Stronger than any Legendary!');
    const mon = makeMon(d.sp, d.lv);
    if (Math.random() < rankedOdds()) mon.rk = 1;
    const r = await battle({ wild: mon, legend: true, apex: !!SP[d.sp].apex });
    if (r === 'caught') { G.flags[d.flag] = 1; removeNpc(n.id); saveGame(); }
    else if (r === 'win') { removeNpc(n.id); await say(SP[d.sp].name + ' fades away... It might come back if you return later.'); }
    else if (r === 'lose') await blackout();
  }

  /* TornTaxi: travel between towns you've visited. Drivers wait in every Tornie Clinic. */
  const TOWNS = {
    maple: ['Maple Hollow', 'maple', 9, 13, 'up'], westgate: ['Westgate', 'westgate', 5, 7, 'down'], midtown: ['Midtown', 'midtown', 5, 7, 'down'],
    docks: ['The Docks', 'docks', 5, 8, 'down'], park: ['Torn City Park', 'park', 5, 8, 'down'], industrial: ['Industrial Zone', 'industrial', 5, 7, 'down'],
    casino: ['Casino Strip', 'casino', 5, 7, 'down'], hospdist: ['Old Hospital District', 'hospdist', 5, 7, 'down'], northridge: ['Northridge', 'northridge', 5, 7, 'down'],
    plaza: ['Council Plaza', 'plaza', 5, 8, 'down']
  };
  async function taxi() {
    const fare = 150, here = W.map.exitTown;
    const list = Object.keys(TOWNS).filter(function (k) { return G.visited && G.visited[k] && k !== here; });
    if (!list.length) { await say('DRIVER: TornTaxi, at your service! Visit a few more towns and I can run you between them.'); return; }
    const d = await say('DRIVER: TornTaxi! Anywhere you\'ve been, $' + fare + ' a ride. Where to?', { hold: true });
    const i = await menu(list.map(function (k) { return { label: TOWNS[k][0], right: '$' + fare }; }).concat(['CANCEL']), { x: VW - 156, y: 4, w: 152, visible: 7 });
    pop(d);
    if (i < 0 || i >= list.length) return;
    if (G.money < fare) { await say('DRIVER: Sorry pal, no cash, no ride.'); return; }
    G.money -= fare;
    const t = TOWNS[list[i]];
    seq([[0, 300, 0.12, 'sawtooth', 0.03, 200], [150, 400, 0.12, 'sawtooth', 0.03, 260]]);
    await fadeOut(0.4); loadMap(t[1], t[2], t[3], t[4]); await wait(0.3); await fadeIn(0.4);
    await say('DRIVER: Here we are, ' + t[0] + '. Mind the potholes!');
  }

  /* Map templates for Clinics, Shops and Arenas */
  function makeClinic(id, outMap, dx, dy, town) {
    defMap('centre_' + id, {
      name: 'Tornie Clinic', bg: 'indoor', border: 'w', indoor: true, tiles: 'O', exitTown: town,
      rows: ['wwwwwwwwww', 'wwwwwwwwww', 'gOOHOOOOOg', 'OkkkkkkOOP', 'OOOOOOOOOO', 'OOttOOOttO', 'OOOOOOOOOO', 'OOOOmmOOOO'],
      warps: mats([4, 5], 7, outMap, dx, dy + 1),
      npcs: [
        { id: 'nurse', x: 4, y: 2, dir: 'down', pal: 'nurse', move: 'still', run: nurseTalk },
        { id: 'taxi', x: 1, y: 5, dir: 'right', pal: 'driver', move: 'look', run: taxi },
        { id: 'coach', x: 8, y: 4, dir: 'left', pal: 'man', move: 'look', run: moveCoach }
      ]
    });
  }
  /* Move Coach (in every Tornie Clinic): teaches a Tornie any move from its own move list that it is already
     high enough level for, for a small fee. This is how Tornies caught before an update pick up the new moves
     they would have learned on the way, and how any Tornie gets back a move it dropped. */
  const COACH_FEE = 500;
  function coachMoves(mon) {
    const out = [], seen = {};
    (SP[mon.sp].learn || []).forEach(function (l) {
      if (l[0] <= mon.lv && MOVES[l[1]] && !seen[l[1]] && !mon.moves.some(function (x) { return x.id === l[1]; })) { seen[l[1]] = 1; out.push(l); }
    });
    return out.sort(function (a, b) { return b[0] - a[0]; });   // newest first
  }
  async function moveCoach() {
    await say('MOVE COACH: I teach Tornies any move they\'re high enough level for. $' + COACH_FEE + ' a lesson.');
    while (true) {
      const t = await partyScreen({ pick: true, prompt: 'Which Tornie needs a lesson?' });
      if (t === null) { await say('MOVE COACH: Come back any time.'); return; }
      const mon = G.party[t], list = coachMoves(mon);
      if (!list.length) { await say('MOVE COACH: ' + monName(mon) + ' already knows everything it can learn at its level. Train it up and come back!'); continue; }
      let sel = 0;
      const i = await menu(list.map(function (l) { return { label: MOVES[l[1]].name, right: 'Lv ' + l[0] }; }).concat(['CANCEL']), {
        x: 4, y: 4, w: 150, visible: 6, onMove: function (k) { sel = k; },
        draw: function () { moneyBox(); if (list[sel]) drawMoveInfo(list[sel][1], 4, VH - 58, VW - 8, 54, { name: true, right: '$' + COACH_FEE }); }
      });
      if (i < 0 || i >= list.length) continue;
      const mv = list[i][1];
      if (G.money < COACH_FEE) { await say('MOVE COACH: A lesson is $' + COACH_FEE + '. Come back when you have the cash.'); return; }
      if (!(await yesno('MOVE COACH: Teach ' + MOVES[mv].name + ' to ' + monName(mon) + ' for $' + COACH_FEE + '?'))) continue;
      if (await learnMove(mon, mv, false)) { G.money -= COACH_FEE; sfx.point(); saveGame(); await say('MOVE COACH: Good lesson. That\'s $' + COACH_FEE + '.'); }
      if (!(await yesno('MOVE COACH: Another lesson?'))) { await say('MOVE COACH: Keep training!'); return; }
    }
  }
  function makeShop(id, outMap, dx, dy, stock, extra) {
    defMap('mart_' + id, {
      name: 'Tornie Supplies', bg: 'indoor', border: 'w', indoor: true, tiles: 'O',
      rows: ['wwwwwwww', 'wwwwwwww', 'OOOBBBBB', 'kkkOOOOO', 'OOOOOOOO', 'OOOOBBBB', 'OOOOOOOO', 'OOOmmOOO'],
      warps: mats([3, 4], 7, outMap, dx, dy + 1),
      npcs: [{ id: 'clerk', x: 1, y: 2, dir: 'down', pal: 'clerk', move: 'still', run: function () { return martTalk(stock); } }].concat(extra || [])
    });
  }
  // A 10x14 arena. deco: the obstacle tile. trainers: [{ id, x, y, dir, pal, trainer, sight, before, after }].
  function makeArena(id, o) {
    const D = o.deco || 'R';
    const rows = ['wwwwwwwwww', 'wwwwwwwwww', 'GGGGGGGGGG', 'G' + D + 'GGGGGG' + D + 'G', 'GGGGGGGGGG', D + D + D + 'GGGG' + D + D + D, 'GGGGGGGGGG', 'GGG' + D + 'GG' + D + 'GGG', 'GGGGGGGGGG', D + D + 'GGGGGG' + D + D, 'GGGGGGGGGG', 'GxGGGGGGxG', 'GGGGGGGGGG', 'GGGGmmGGGG']
      .map(function (r) { return o.floor ? r.replace(/G/g, o.floor) : r; });
    defMap('gym_' + id, {
      name: o.name, bg: o.bg || 'rock', border: 'w', indoor: true, tiles: o.floor || 'G',
      rows: rows, warps: mats([4, 5], 13, o.outMap, o.dx, o.dy + 1),
      statue: function () { return o.name.toUpperCase() + '|Medal winners: ' + (G.badges.indexOf(o.medal) >= 0 ? '{P}' : '?????'); },
      npcs: [{ id: 'leader_' + id, x: 4, y: 2, dir: 'down', pal: o.pal, move: 'still', run: function (n) { return arenaLeader(id, n); } }]
        .concat(o.trainers || [])
        .concat([{ id: 'guide_' + id, x: 7, y: 12, dir: 'left', pal: 'guide', move: 'look', run: function () { return say(G.badges.indexOf(o.medal) >= 0 ? 'You did it! That medal looks good on you, champ.' : o.guide); } }])
    });
  }

  /* Arena Leaders */
  const MEDALS = [['brick', 'Brick', '#b06a30'], ['volt', 'Volt', '#f0c030'], ['reef', 'Reef', '#3a88d8'], ['ivy', 'Ivy', '#4ab04a'], ['forge', 'Forge', '#8a929e'], ['ace', 'Ace', '#d050c0'], ['graves', 'Graves', '#6a5a8a'], ['rhea', 'Rhea', '#7038f8']];
  async function arenaLeader(key, npc) {
    const A = ARENAS[key], nm = A.name.toUpperCase();
    if (G.badges.indexOf(A.medal) >= 0) { await say(nm + ': ' + A.after); return; }
    if (A.locked && A.locked()) { await say(nm + ': ' + A.lockedText); return; }
    await say(nm + ': ' + A.intro);
    const r = await trainerBattle(A.trainer, { npc: npc });
    if (r !== 'win') return;
    await say(nm + ': ' + A.win);
    G.badges.push(A.medal); jingle('badge');
    await say('{P} was awarded the ' + A.medal.toUpperCase() + ' MEDAL!');
    await fieldDiscGift(A.medal, nm);
    if (A.disc) { addItem(A.disc, 1); jingle('item'); await say(nm + ': Take this as well. It\'s a Training Disc for ' + MOVES[ITEMS[A.disc].move].name + '.'); }
    if (A.then) await A.then();
    saveGame();
  }
  function hasMedals(n) { return G.badges.length >= n; }
  function medal(id) { return G.badges.indexOf(id) >= 0; }

  /* Hall of Fame and credits */
  function hallOfFame() {
    return new Promise(function (res) {
      const team = G.party.slice(), m = { t: 0, phase: 0 };
      const CRED = [
        ['TORNIES', 16], ['', 8], ['A Torn Arcade game', 9], ['created by Eaglewing [571041]', 9], ['', 20],
        ['STARRING', 11], ['{P} and the team', 9], ['', 8], ['THE TORN COUNCIL', 11], ['bogie   CloudJumper', 9], ['PrincessJulie   Jack-o', 9], ['', 10], ['CHAMPION', 11], ['Chedburn', 9], ['', 14],
        ['ARENA LEADERS', 11], ['Brick  Volta  Captain Reef  Ivy', 9], ['Forge  Madame Ace  Dr. Graves  Rhea', 9], ['', 14],
        ['WITH', 11], ['Prof. Quinn  Vince  Mom', 9], ['and the Racket (sort of)', 9], ['', 14],
        ['MADE FOR THE PLAYERS OF', 11], ['TORN CITY', 13], ['', 20], ['Thanks for playing!', 12], ['', 10], ['The adventure isn\'t over...', 9]
      ];
      m.btn = function (b) { if ((b === 'a' || b === 'b' || b === 'start') && m.phase === 2) { pop(m); res(); } else if (b === 'a' && m.phase === 0 && m.t > 2) { m.phase = 1; m.t = 0; } };
      m.update = function (dt) { m.t += dt * (held.a ? 3 : 1); if (m.phase === 0 && m.t > 9) { m.phase = 1; m.t = 0; } if (m.phase === 1 && m.t > CRED.length * 1.1 + 6) m.phase = 2; };
      m.draw = function () {
        screenBg('#2a1a4a', '#0a0818');
        if (m.phase === 0) {
          text('HALL OF FAME', VW / 2, 10, '#ffd65a', { sz: 14, al: 'center', light: true });
          text('Champion: ' + G.name, VW / 2, 30, '#ffffff', { sz: 9, al: 'center', light: true });
          team.forEach(function (mon, k) {
            const x = 20 + (k % 3) * 70, y = 46 + Math.floor(k / 3) * 56, show = m.t > 0.6 + k * 0.5;
            if (!show) return;
            ctx.drawImage(monSprite(mon.sp, false, mon.rk), x, y, 48, 48);
            text(monName(mon) + ' Lv' + mon.lv, x + 24, y + 46, '#c8d4f0', { sz: 6.5, al: 'center', light: true });
          });
          return;
        }
        let y = VH - (m.t * 22);
        CRED.forEach(function (c) { if (y > -20 && y < VH + 10) text(fillNames(c[0]), VW / 2, y, c[1] >= 11 ? '#ffd65a' : '#e8ecf8', { sz: c[1], al: 'center', light: true }); y += c[1] + 7; });
        if (m.phase === 2) text('Press A', VW / 2, VH - 16, '#8a94b4', { sz: 7, al: 'center', sh: false });
      };
      push(m); jingle('badge');
    });
  }

