  async function slickTalk(n) {
    await say('LIEUTENANT SLICK: Huh. You\'re the rookie who embarrassed Knuckles.|These Tornies are shipping out tonight on the SS Bogie. Black market prices are through the roof. Nothing personal, pal.');
    const r = await trainerBattle('slick', { npc: n });
    if (r !== 'win') return;
    G.flags.warehouse = 1;
    await say('SLICK: Unbelievable. Fine, take the cargo. We\'ve got bigger plans anyway.|Don Varro is close to finding the Origin Shard. Once he has it, every Tornie in Torn City will do what he says.');
    removeNpc('slick'); sfx.click();
    await fadeOut(0.3); await wait(0.3); await fadeIn(0.3);
    await say('{P} opened the crates. Dozens of stolen Tornies scamper out and race back to their owners!');
    await say('CAPTAIN REEF: Ha! Free at last. You\'ve got guts, trainer.|Come and see me at the Docks Arena when you\'re ready. And the thugs blocking Route 5 have scarpered, so the road to Midtown is clear too.');
    removeNpc('reef_tied');
    saveGame();
  }

