  async function knuckles2Talk(n) {
    await say('KNUCKLES: Oh, come ON. Not you again!|Fine. The boss says this factory has the old Genesis plans. Where the vault is, how it opens. And I\'m NOT going back empty-handed.');
    const r = await trainerBattle('knuckles2', { npc: n });
    if (r !== 'win') return;
    G.flags.factory = 1;
    await say('KNUCKLES: That\'s it. I quit. I\'m getting a normal job. Maybe at the Feathery Hotel.');
    await say('KNUCKLES: Here, take this stupid key card. Opens the Racket HQ under the Casino. I don\'t want it anymore.|Don Varro is in there planning the big job. The bank vault. The Shard. All of it.');
    addItem('cardkey', 1); jingle('get');
    await say('{P} got the RACKET CARD KEY!');
    removeNpc('knuckles2');
    await phoneMsg('Prof. Quinn', 'Knuckles gave you a key to the Racket HQ?! {P}, that\'s huge.|Don\'t go in alone. Get stronger first. The Casino Strip is east along Route 10, once the road reopens.');
    saveGame();
  }
