  async function varro1Talk(n) {
    await say('DON VARRO: So. You\'re the nuisance who\'s been ruining my year.|Knuckles, Slick, half my crew... all beaten by a rookie with a phone full of pets.');
    await say('DON VARRO: Do you know what\'s in the Torn City Bank vault? The Origin Shard. The reason Tornies exist.|Whoever holds it can make Tornies stronger than anything this city has ever seen. Make them obey.');
    await say('DON VARRO: Chedburn locked it away like a museum piece. What a waste.|I started out picking pockets on Route 1 with a scruffy little Pickpockit. Now I\'m going to own this whole city.');
    const r = await trainerBattle('varro1', { npc: n });
    if (r !== 'win') return;
    G.flags.hq = 1;
    await say('DON VARRO: ...Hm. Hm hm hm. Fine. You win this round.|But you\'re too late. My diggers broke through under the bank this morning. The vault door is the only thing left.');
    await say('DON VARRO: And I\'ve got the key right... here...|...Where\'s my key?');
    await say('Don Varro pats down every pocket. Then he spots it, on the floor by your feet.');
    await say('DON VARRO: No matter! A wall is just a door that hasn\'t met enough dynamite! TO THE TUNNEL!');
    seq([[0, 200, 0.25, 'sawtooth', 0.05, 60]]); await fadeOut(0.3); removeNpc('varro1'); await fadeIn(0.3);
    await say('Don Varro dived through a hatch behind his desk and disappeared!');
    addItem('vaultkey', 1); jingle('get');
    await say('{P} picked up the VAULT KEY!');
    await phoneMsg('Chedburn', '{P}, the police just told me you raided the Racket HQ. Remarkable.|If Varro is heading for the vault, I\'ll meet you at Torn City Bank in Midtown. Hurry!');
    saveGame();
  }

