  async function castawayTalk() {
    if (G.flags.castaway) { await say('CASTAWAY: I think I\'ll stay a bit longer. The coconuts are free and nobody can mug me here.'); return; }
    await say('A man with an enormous beard leaps out of the bushes!|CASTAWAY: A PERSON! A real person! What year is it?!');
    await say('CASTAWAY: I came out here years ago to escape Torn City. Too many muggings. Too many hospital trips.|Tell me, is the Bazaar still open? Do people still sell plushies for a fortune?');
    await say('CASTAWAY: Ha! Some things never change. Here, take this. I found it washed up on the beach.|It\'s no use to me. I\'ve got nothing to catch out here but coconuts.');
    addItem('capsule3', 3); addItem('energy_bar', 1); jingle('get'); G.flags.castaway = 1;
    await say('{P} got 3 Armoured Capsules and an Energy Bar!');
    saveGame();
  }

