    if (!G.flags.champion) { await say('DUKE: ...'); await say('Duke doesn\'t even look up from his newspaper.'); return; }
    await say('DUKE: So you\'re the trainer who took down Don Varro. That pickpocket worked for me, once upon a time.|Before he got ideas.');
    await say('DUKE: I\'ve been the toughest guy in this city since before there were Tornies. Everybody comes for me eventually.|Let\'s see what the Champion\'s made of.');
    const r = await trainerBattle('duke', { npc: n });
    if (r !== 'win') return;
    G.flags.duke = 1;
    await say('DUKE: Hah! Not bad. Not bad at all.|Here. A little something from my "collection". Don\'t ask where it came from.');
    G.money += 50000; addItem('energy_bar', 5); addItem('capsule3', 10); jingle('get');
