  function noteMidi(n) { const m = /^([A-G])([#b]?)(\d)$/.exec(n); return 12 * (Number(m[3]) + 1) + NOTE_IX[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0); }
