  /* ================= Field moves, Field Discs and battle boosters ================= */
  // Training Discs are single use. Field Discs (reusable) teach the five moves you can use out in the world. Each is handed over
  // by an Arena Leader with their medal. A Field Disc is never used up. Using a field move needs the disc AND a
  // healthy Tornie in your team that knows the move.
  mv('wave_rider', 'Wave Rider', 'Water', 'S', 90, 100, 15);
  mv('sky_lift', 'Sky Lift', 'Air', 'P', 90, 95, 15);
  mv('heavy_lift', 'Heavy Lift', 'Brawl', 'P', 80, 100, 15);
  mv('floodlight', 'Floodlight', 'Electric', 'S', 50, 100, 20, { stat: [['spe', -1]], c: 30 });
  const FIELD = {
    field_smash: { move: 'rock_smash', medal: 'brick', types: ['Brawl', 'Stone', 'Earth', 'Metal', 'Fire', 'Street'], use: 'Breaks boulders out in the world.' },
    field_light: { move: 'floodlight', medal: 'volt', types: ['Electric', 'Fire', 'Mind', 'Spirit'], use: 'Lights up dark places.' },
    field_surf:  { move: 'wave_rider', medal: 'reef', types: ['Water', 'Ice'], use: 'Ride across water. Face the water and press A.' },
    field_lift:  { move: 'heavy_lift', medal: 'forge', types: ['Brawl', 'Stone', 'Earth', 'Metal', 'Mythic'], use: 'Pushes boulders out of the way.' },
    field_fly:   { move: 'sky_lift', medal: 'ace', types: ['Air', 'Mythic'], use: 'Fly to any town you have visited, from anywhere outdoors.' }
  };
  Object.keys(FIELD).forEach(function (id) {
    const f = FIELD[id], M = MOVES[f.move];
    ITEMS[id] = { name: 'Field Disc: ' + M.name, price: 0, kind: 'field', move: f.move, desc: 'Teaches ' + M.name + ' (' + M.type + ') to ' + f.types.join(', ') + ' Tornies. ' + f.use + ' Never used up.' };
    ITEM_ORDER.splice(ITEM_ORDER.indexOf('rod'), 0, id);
  });
  // Training Discs are used up when a Tornie learns the move. Only Field Discs are reusable.
