  function fieldCanLearn(mon, id) { return SP[mon.sp].allDiscs || FIELD[id].types.some(function (t) { return SP[mon.sp].types.indexOf(t) >= 0; }) || SP[mon.sp].learn.some(function (l) { return l[1] === FIELD[id].move; }); }
