  // Called after each step: get off the water when you reach land, and meet water Tornies while riding the waves.
  function surfStep(m, here) {
    if (!G.surf) return false;
    if (here !== '~') { G.surf = 0; return false; }
    if (m.fish && !G.repel && G.party.some(alive) && Math.random() < 0.06) { runScript(function () { return wildBattle(m.fish); }); return true; }
    return false;
  }
  // The rider: a little surfboard under the player while on the water.
