    const x = (-40 + p * 320) * SC, band = g.createLinearGradient(x - 18 * SC, 0, x + 18 * SC, LOGO_H * SC);
    band.addColorStop(0, 'rgba(255,255,255,0)'); band.addColorStop(0.5, 'rgba(255,255,255,.55)'); band.addColorStop(1, 'rgba(255,255,255,0)');
