    rg.addColorStop(0, 'rgba(255,250,230,' + mg.toFixed(3) + ')'); rg.addColorStop(1, 'rgba(255,250,230,0)'); ctx.fillStyle = rg; ctx.fillRect(150, 0, 90, 60);
