          ctx.lineWidth = sel ? 2 : 1; ctx.strokeStyle = sel ? '#f08a30' : '#8aa8bc'; ctx.stroke();
          if (!drawPortrait(ctx, 'outfit' + k, x - 3, 30, 54)) drawPerson(ctx, o, sel ? ['down', 'left', 'up', 'right'][Math.floor(T * 1.5) % 4] : 'down', 0, x, 40, 3);
          text(o.name, x + 24, 90, '#303846', { sz: 7.5, al: 'center' });
