    introShow = { who: 'prof', mon: 0 };
    scene = introScene;
    await fadeIn(0.3);
    await say('PROF. QUINN: Oh! You must be my new neighbour.|I\'m Quinn. I study the creatures that have taken over this city.');
    introShow.mon = 18; cry(18);
    await say('We call them Tornies. They nest in parks, sewers, rooftops, even the casino vents.|Some folks keep them as pets. The brave ones fight with them.');
    introShow.mon = 0;
    await say('Anyway, where are my manners? Who am I talking to?');
    G.name = await askName('What\'s your name?', 'Alex', 10);
    G.outfit = await outfitPicker();
    introShow.who = 'prof';
    await say('{P}! Nice to finally put a name to the face.');
    introShow.who = 'rival';
