  /* ---------- Main loop ---------- */
  function render() {
    ctx.setTransform(SC, 0, 0, SC, 0, 0); ctx.imageSmoothingEnabled = false;
    fr(0, 0, VW, VH, '#000');
    if (scene) scene.draw();
    // Battles and other screens are quiet moments: carry on drawing the current map in the background.
    if (scene !== worldScene && W.map && IWC.id === W.map && IWC.camX !== undefined && iwOn && store.get('detailMaps', true) !== false) iwPrebake(W.map, IWC.camX, IWC.camY);
    modals.forEach(function (m) { if (m.draw) m.draw(); });
    if (flash > 0) fr(0, 0, VW, VH, 'rgba(255,255,255,' + Math.min(1, flash) + ')');
    if (fade > 0) fr(0, 0, VW, VH, 'rgba(0,0,0,' + Math.min(1, fade) + ')');
  }
  function frame(ts) {
    raf = requestAnimationFrame(frame);
    const dt = Math.min(0.05, (ts - (last || ts)) / 1000); last = ts; T += dt;
    try {
      if (G && scene && scene.timed) G.time += dt;
      flash = Math.max(0, flash - dt * 2.5);
      const ps = presses; presses = [];
      ps.forEach(function (b) { const h = modals.length ? modals[modals.length - 1] : scene; if (h && h.btn) h.btn(b); });
      updateTweens(dt);
      if (scene && scene.update) scene.update(dt);
      modals.slice().forEach(function (m) { if (m.update) m.update(dt); });
      render();
      if (G) drawToasts(dt);
      musicTick();
    } catch (e) { console.error('[Tornies]', e); }
  }
  function fit() {
    if (!built || !active) return;
    const touch = ptWrap.classList.contains('ta-pt-touch'), stage = $(panel, '.ta-stage'), land = root.classList.contains('ta-land');
    let availW = stage.clientWidth - 16, availH = stage.clientHeight - 16;
    if (touch) { if (land) availW -= 2 * 150; else availH -= ($(panel, '.ta-pt-pad').offsetHeight || 170) + 10; }
    const s = Math.max(0.3, Math.min(availW / 720, availH / 480, 1.6));
    cv.style.width = Math.floor(720 * s) + 'px'; cv.style.height = Math.floor(480 * s) + 'px';
  }
  window.addEventListener('resize', function () { if (active) fit(); });
  // Save when the page is closed or hidden, as long as nothing is mid-way (battle, dialog).
  function safeSave() { if (G && scene === worldScene && !W.busy && !modals.length) saveGame(); }
  window.addEventListener('pagehide', safeSave);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { safeSave(); return; }
    // The arcade stops the current game when the tab is hidden; restart the Tornies loop when it comes back.
    if (isOpen && current === 'pocket' && built && !active) games.pocket.enter();
  });
  function build() {
    built = true;
    cv.width = VW * SC; cv.height = VH * SC;
    ctx = cv.getContext('2d');
    scene = titleScene;
  }
  
