    function dust(x, y, n) { for (let i = 0; i < n; i++) parts.push({ x: x, y: y, vx: rand(-1.5, 1.5), vy: rand(-2, 0), g: -0.5, t: 0, life: rand(0.4, 0.8), puff: 1, r: rand(0.1, 0.25), col: 'rgba(230,220,200,' }); }
    const SHARD = { wood: ['#c98f4f', '#8a5a2a', '#e8b878'], glass: ['#e8faff', '#9fd8f0', '#ffffff'], stone: ['#a4a8b0', '#6a6e78', '#c4c8d0'], steel: ['#d0d6e0', '#7a828e', '#f4f6fa'], dirty: ['#e8c020', '#2a2a2a', '#f0e070'] };
