          for (let k = 0; k < 3; k++) { g.strokeStyle = 'rgba(255,240,255,' + (0.5 - k * 0.12).toFixed(2) + ')'; g.lineWidth = 2 - k * 0.5; let x = 160 + k * 300, y = 0; g.beginPath(); g.moveTo(x, y); while (y < gy - 140) { x += (R() - 0.5) * 50; y += 20 + R() * 20; g.lineTo(x, y); } g.stroke(); }
          for (let i = 0; i < 90; i++) { g.strokeStyle = 'rgba(160,170,200,.25)'; g.lineWidth = 1; const x = R() * W, y = R() * gy; g.beginPath(); g.moveTo(x, y); g.lineTo(x - 6, y + 16); g.stroke(); }
          skyline(gy, 80, 210, '#0c0608', '#ff3a2a', 0.1, 34, 70);
