        horn: [[0, 330, 0.18, 'sawtooth', 0.04], [200, 330, 0.25, 'sawtooth', 0.04]], clear: [[0, 660, 0.08, 'triangle', 0.05], [90, 990, 0.12, 'triangle', 0.05]]
